<?php
namespace App\Filament\Resources\FoundationSkDocuments\Tables;
use Filament\Actions\Action;
use App\Models\FoundationSkDocument;use Filament\Actions\DeleteAction;use Filament\Actions\EditAction;use Filament\Tables\Columns\TextColumn;use Filament\Tables\Filters\SelectFilter;use Filament\Tables\Table;use App\Models\FoundationSkTemplate;use App\Models\User;
class FoundationSkDocumentsTable { public static function configure(Table $table): Table { return $table->columns([TextColumn::make('user.name')->label('Nama')->searchable()->sortable(),TextColumn::make('user.employee.school.name')->label('Sekolah')->searchable(),TextColumn::make('tahun_sk')->label('Tahun')->sortable(),TextColumn::make('template.name')->label('Template'),TextColumn::make('original_filename')->label('Nama File'),TextColumn::make('file_size')->label('Ukuran')->formatStateUsing(fn($s)=>number_format(((int)$s)/1024,1).' KB'),TextColumn::make('source_type')->label('Sumber'),TextColumn::make('created_at')->label('Diunggah')->dateTime('d-m-Y H:i')])->filters([SelectFilter::make('user_id')->relationship('user','name')->searchable()->preload(),SelectFilter::make('sk_template_id')->relationship('template','name')->searchable()->preload(),SelectFilter::make('tahun_sk')->options(fn()=>FoundationSkDocument::query()->distinct()->orderByDesc('tahun_sk')->pluck('tahun_sk','tahun_sk')->all()),SelectFilter::make('source_type')->options(['single'=>'Upload satu','batch'=>'Import batch'])])->recordActions([Action::make('download')->label('Unduh')->url(fn(FoundationSkDocument $record): string=>route('foundation-sk.documents.download',$record))->openUrlInNewTab(),EditAction::make(),DeleteAction::make()]); } }
